function chain(...fns) {
  return (initial) => {
    let result = initial;
    for (const fn of fns) {
      result = fn(result);
    }
    return result;
  };
}
const process = chain(
  x => x + 1,
  x => x * 2,
  x => x - 3
);
console.log(process(5));
